#include <bits/stdc++.h>
using namespace std;

int pw6[6];
int need[5], price[5], have;
struct Plan { vector<pair<int, int>> items; int price; };
vector<Plan> plans;
int memo[7776];

int solve(int state) {
    int &res = memo[state];
    if (res != -1) return res;

    int rem[5], t = state;
    bool allZero = true;
    for (int i = 0; i < have; i++) {
        rem[i] = t % 6; t /= 6;
        if (rem[i]) allZero = false;
    }
    if (allZero) return res = 0;

    // 兜底：剩余全按原价
    res = 0;
    for (int i = 0; i < have; i++) res += rem[i] * price[i];

    // 枚举方案（可重复购买）
    for (const Plan &pl : plans) {
        if (pl.items.empty()) continue;
        int ns = state;
        bool ok = true;
        for (auto &it : pl.items) {
            if (rem[it.first] < it.second) { ok = false; break; }
            ns -= it.second * pw6[it.first];
        }
        if (!ok) continue;
        res = min(res, pl.price + solve(ns));
    }
    return res;
}

int main() {
    pw6[0] = 1;
    for (int i = 1; i <= 5; i++) pw6[i] = pw6[i - 1] * 6;

    int s;
    cin >> s;
    vector<Plan> raw;
    for (int i = 0; i < s; i++) {
        int n, p;
        cin >> n >> p;
        vector<pair<int, int>> items;
        for (int j = 0; j < n; j++) {
            int c, k;
            cin >> c >> k;
            items.push_back({c, k});
        }
        raw.push_back({items, p});
    }

    int b;
    cin >> b;
    int slot[1000];
    fill(slot, slot + 1000, -1);
    have = 0;
    for (int i = 0; i < b; i++) {
        int c, k, p;
        cin >> c >> k >> p;
        if (slot[c] == -1) slot[c] = have++;
        need[slot[c]] = k;
        price[slot[c]] = p;
    }

    // 方案里只保留落在清单内的商品，合并同一编号的数量；全不在清单内的丢弃
    for (auto &pl : raw) {
        int cnt[5] = {0};
        for (auto &it : pl.items) {
            if (slot[it.first] != -1) cnt[slot[it.first]] += it.second;
        }
        Plan np;
        np.price = pl.price;
        for (int i = 0; i < have; i++) if (cnt[i]) np.items.push_back({i, cnt[i]});
        if (!np.items.empty()) plans.push_back(np);
    }

    int start = 0;
    for (int i = 0; i < have; i++) start += need[i] * pw6[i];

    fill(memo, memo + 7776, -1);
    cout << solve(start) << endl;
    return 0;
}
